CREATE TABLE process3_document (id INTEGER PRIMARY KEY, stock_id TEXT NOT NULL, stock_label TEXT NOT NULL);
CREATE TABLE process3_stock_pose (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES process3_document(id), position_x REAL, position_y REAL, position_z REAL, axis_x REAL, axis_y REAL, axis_z REAL, angle REAL, position_x_ieee754_bits INTEGER NOT NULL, position_x_numeric_class TEXT NOT NULL, position_y_ieee754_bits INTEGER NOT NULL, position_y_numeric_class TEXT NOT NULL, position_z_ieee754_bits INTEGER NOT NULL, position_z_numeric_class TEXT NOT NULL, axis_x_ieee754_bits INTEGER NOT NULL, axis_x_numeric_class TEXT NOT NULL, axis_y_ieee754_bits INTEGER NOT NULL, axis_y_numeric_class TEXT NOT NULL, axis_z_ieee754_bits INTEGER NOT NULL, axis_z_numeric_class TEXT NOT NULL, angle_ieee754_bits INTEGER NOT NULL, angle_numeric_class TEXT NOT NULL);
CREATE TABLE process3_stock_payload (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES process3_document(id), native_id TEXT NOT NULL, label TEXT NOT NULL);
CREATE TABLE process3_stock_payload_pose (id INTEGER PRIMARY KEY, stock_payload_id INTEGER NOT NULL REFERENCES process3_stock_payload(id), position_x REAL, position_y REAL, position_z REAL, axis_x REAL, axis_y REAL, axis_z REAL, angle REAL, position_x_ieee754_bits INTEGER NOT NULL, position_x_numeric_class TEXT NOT NULL, position_y_ieee754_bits INTEGER NOT NULL, position_y_numeric_class TEXT NOT NULL, position_z_ieee754_bits INTEGER NOT NULL, position_z_numeric_class TEXT NOT NULL, axis_x_ieee754_bits INTEGER NOT NULL, axis_x_numeric_class TEXT NOT NULL, axis_y_ieee754_bits INTEGER NOT NULL, axis_y_numeric_class TEXT NOT NULL, axis_z_ieee754_bits INTEGER NOT NULL, axis_z_numeric_class TEXT NOT NULL, angle_ieee754_bits INTEGER NOT NULL, angle_numeric_class TEXT NOT NULL);
CREATE TABLE process3_solid (id INTEGER PRIMARY KEY, variant TEXT NOT NULL);
CREATE TABLE process3_solid_box (id INTEGER PRIMARY KEY, solid_id INTEGER NOT NULL REFERENCES process3_solid(id), width REAL, depth REAL, height REAL, width_ieee754_bits INTEGER NOT NULL, width_numeric_class TEXT NOT NULL, depth_ieee754_bits INTEGER NOT NULL, depth_numeric_class TEXT NOT NULL, height_ieee754_bits INTEGER NOT NULL, height_numeric_class TEXT NOT NULL);
CREATE TABLE process3_solid_cylinder (id INTEGER PRIMARY KEY, solid_id INTEGER NOT NULL REFERENCES process3_solid(id), radius REAL, height REAL, radius_ieee754_bits INTEGER NOT NULL, radius_numeric_class TEXT NOT NULL, height_ieee754_bits INTEGER NOT NULL, height_numeric_class TEXT NOT NULL);
CREATE TABLE process3_solid_sphere (id INTEGER PRIMARY KEY, solid_id INTEGER NOT NULL REFERENCES process3_solid(id), radius REAL, radius_ieee754_bits INTEGER NOT NULL, radius_numeric_class TEXT NOT NULL);
CREATE TABLE process3_solid_imported_mesh (id INTEGER PRIMARY KEY, solid_id INTEGER NOT NULL REFERENCES process3_solid(id), mesh_url TEXT NOT NULL);
CREATE TABLE process3_solid_imported_solid (id INTEGER PRIMARY KEY, solid_id INTEGER NOT NULL REFERENCES process3_solid(id), solid_handle TEXT NOT NULL);
CREATE TABLE process3_solid_reference (id INTEGER PRIMARY KEY, solid_id INTEGER NOT NULL REFERENCES process3_solid(id), reference_id TEXT NOT NULL);
CREATE TABLE process3_stock_payload_solid (id INTEGER PRIMARY KEY, stock_payload_id INTEGER NOT NULL REFERENCES process3_stock_payload(id), solid_id INTEGER NOT NULL REFERENCES process3_solid(id));
CREATE TABLE process3_machine (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES process3_document(id), ordinal INTEGER NOT NULL, native_id TEXT NOT NULL, label TEXT NOT NULL, icon_id TEXT NOT NULL, catalog_id TEXT);
CREATE TABLE process3_capability (id INTEGER PRIMARY KEY, machine_id INTEGER NOT NULL REFERENCES process3_machine(id), ordinal INTEGER NOT NULL, native_id TEXT NOT NULL, label TEXT NOT NULL, icon_id TEXT NOT NULL, recipe_variant TEXT NOT NULL);
CREATE TABLE process3_recipe_disc_cut (id INTEGER PRIMARY KEY, capability_id INTEGER NOT NULL REFERENCES process3_capability(id), diameter_parameter TEXT NOT NULL, kerf_parameter TEXT NOT NULL);
CREATE TABLE process3_recipe_blade_cut (id INTEGER PRIMARY KEY, capability_id INTEGER NOT NULL REFERENCES process3_capability(id), kerf_parameter TEXT NOT NULL, length_parameter TEXT NOT NULL, depth_parameter TEXT NOT NULL);
CREATE TABLE process3_recipe_pocket_cut (id INTEGER PRIMARY KEY, capability_id INTEGER NOT NULL REFERENCES process3_capability(id), diameter_parameter TEXT NOT NULL, depth_parameter TEXT NOT NULL);
CREATE TABLE process3_recipe_bore_drill (id INTEGER PRIMARY KEY, capability_id INTEGER NOT NULL REFERENCES process3_capability(id), radius_parameter TEXT NOT NULL, depth_parameter TEXT NOT NULL);
CREATE TABLE process3_recipe_cylinder_attach (id INTEGER PRIMARY KEY, capability_id INTEGER NOT NULL REFERENCES process3_capability(id), radius_parameter TEXT NOT NULL, length_parameter TEXT NOT NULL);
CREATE TABLE process3_recipe_box_attach (id INTEGER PRIMARY KEY, capability_id INTEGER NOT NULL REFERENCES process3_capability(id), width_parameter TEXT NOT NULL, depth_parameter TEXT NOT NULL, height_parameter TEXT NOT NULL);
CREATE TABLE process3_parameter (id INTEGER PRIMARY KEY, capability_id INTEGER NOT NULL REFERENCES process3_capability(id), ordinal INTEGER NOT NULL, native_id TEXT NOT NULL, label TEXT NOT NULL, value REAL, value_ieee754_bits INTEGER NOT NULL, value_numeric_class TEXT NOT NULL);
CREATE TABLE process3_rule (id INTEGER PRIMARY KEY, capability_id INTEGER NOT NULL REFERENCES process3_capability(id), ordinal INTEGER NOT NULL, variant TEXT NOT NULL, stock_quantity TEXT NOT NULL, parameter_id TEXT NOT NULL, margin REAL, margin_ieee754_bits INTEGER NOT NULL, margin_numeric_class TEXT NOT NULL);
CREATE TABLE process3_step (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES process3_document(id), ordinal INTEGER NOT NULL, native_id TEXT NOT NULL, label TEXT NOT NULL, enabled INTEGER NOT NULL);
CREATE TABLE process3_step_origin (id INTEGER PRIMARY KEY, step_id INTEGER NOT NULL REFERENCES process3_step(id), machine_id TEXT NOT NULL, capability_id TEXT NOT NULL);
CREATE TABLE process3_measure (id INTEGER PRIMARY KEY, step_id INTEGER NOT NULL REFERENCES process3_step(id), variant TEXT NOT NULL);
CREATE TABLE process3_measure_cut (id INTEGER PRIMARY KEY, measure_id INTEGER NOT NULL REFERENCES process3_measure(id), solid_id INTEGER NOT NULL REFERENCES process3_solid(id));
CREATE TABLE process3_measure_drill (id INTEGER PRIMARY KEY, measure_id INTEGER NOT NULL REFERENCES process3_measure(id), radius REAL, depth REAL, radius_ieee754_bits INTEGER NOT NULL, radius_numeric_class TEXT NOT NULL, depth_ieee754_bits INTEGER NOT NULL, depth_numeric_class TEXT NOT NULL);
CREATE TABLE process3_measure_attach (id INTEGER PRIMARY KEY, measure_id INTEGER NOT NULL REFERENCES process3_measure(id), solid_id INTEGER NOT NULL REFERENCES process3_solid(id));
CREATE TABLE process3_measure_pose (id INTEGER PRIMARY KEY, measure_id INTEGER NOT NULL REFERENCES process3_measure(id), position_x REAL, position_y REAL, position_z REAL, axis_x REAL, axis_y REAL, axis_z REAL, angle REAL, position_x_ieee754_bits INTEGER NOT NULL, position_x_numeric_class TEXT NOT NULL, position_y_ieee754_bits INTEGER NOT NULL, position_y_numeric_class TEXT NOT NULL, position_z_ieee754_bits INTEGER NOT NULL, position_z_numeric_class TEXT NOT NULL, axis_x_ieee754_bits INTEGER NOT NULL, axis_x_numeric_class TEXT NOT NULL, axis_y_ieee754_bits INTEGER NOT NULL, axis_y_numeric_class TEXT NOT NULL, axis_z_ieee754_bits INTEGER NOT NULL, axis_z_numeric_class TEXT NOT NULL, angle_ieee754_bits INTEGER NOT NULL, angle_numeric_class TEXT NOT NULL);
CREATE TABLE process3_stock_solid_child (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES process3_document(id), child_id TEXT NOT NULL, target_artifact_id TEXT NOT NULL, artifact_kind TEXT NOT NULL, standard TEXT NOT NULL, subset TEXT NOT NULL);
CREATE TABLE process3_steps_child (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES process3_document(id), child_id TEXT NOT NULL, target_artifact_id TEXT NOT NULL, artifact_kind TEXT NOT NULL, standard TEXT NOT NULL, subset TEXT NOT NULL);
CREATE TABLE process3_tool_solid_child (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES process3_document(id), ordinal INTEGER NOT NULL, child_id TEXT NOT NULL, target_artifact_id TEXT NOT NULL, artifact_kind TEXT NOT NULL, standard TEXT NOT NULL, subset TEXT NOT NULL);
